SEC = [
 (120, 'కృత్యం 4.1 – పట్టిక 4.1', [
  'నమూనా: పెన్సిల్ (చెక్క) – కాదు; రబ్బరు – కాదు; ఇనుప మేకు – అవును; గుండుసూది/ఉక్కు క్లిప్ – అవును; ప్లాస్టిక్ స్కేలు – కాదు; గాజు గాజులు – కాదు; కాగితం – కాదు; అల్యూమినియం/రాగి నాణెం – కాదు; ఇనుప తాళం చెవి – అవును.',
  'ముగింపు: ఇనుము (నికెల్, కోబాల్ట్) తో చేసిన వస్తువులు మాత్రమే అయస్కాంతానికి అతుక్కున్నాయి – అవి అయస్కాంత పదార్థాలు. చెక్క, రబ్బరు, ప్లాస్టిక్, గాజు, కాగితం, ఇత్తడి – అనయస్కాంత పదార్థాలు.']),
 (122, 'కృత్యం 4.2, 4.3 – ధ్రువాలు, దిక్కులు', [
  'ఇనుప రజను దండ అయస్కాంతం రెండు చివర్లలో ఎక్కువగా, మధ్యలో చాలా తక్కువగా అతుక్కుంటుంది; ఏ ఆకార అయస్కాంతమైనా ధ్రువాల వద్దే ఎక్కువ.',
  'వేలాడదీసిన అయస్కాంతాన్ని ఎన్నిసార్లు తిప్పినా అదే రేఖ వెంట ఆగుతుంది. సూర్యుడు ఉదయించే దిశ (తూర్పు) తెలిస్తే ఆ రేఖ ఉత్తర–దక్షిణ దిశ అని తెలుస్తుంది.']),
 (126, 'కృత్యం 4.4 – దిక్సూచి తయారీ', [
  'రుద్దిన తర్వాత సూది గుండుసూదులను ఆకర్షిస్తే అది అయస్కాంతమైంది. బెండుపై నీటిలో తేలే సూదిని ఎన్నిసార్లు తిప్పినా దాని చివర్లు ఎప్పుడూ ఉత్తర–దక్షిణ దిశలోనే ఆగుతాయి – ఇదే మన దిక్సూచి.']),
 (128, 'కృత్యం 4.5 – రెండు అయస్కాంతాలు', [
  'B ఒక చివరను A దగ్గరకు తెస్తే A దగ్గరకు దొర్లుతుంది (ఆకర్షణ) – విజాతి ధ్రువాలు; మరో చివర తెస్తే A దూరంగా దొర్లుతుంది (వికర్షణ) – సజాతి ధ్రువాలు. కాబట్టి A ఎప్పుడూ దగ్గరకే రాదు.']),
 (130, 'కృత్యం 4.5 (ఇనుప కడ్డీ), 4.6', [
  'ఇనుప కడ్డీ రెండు చివర్లూ అయస్కాంతం రెండు ధ్రువాలకూ ఆకర్షితమవుతాయి – వికర్షణ ఎప్పుడూ జరగదు. కాబట్టి వికర్షణ ద్వారానే అయస్కాంతాన్ని గుర్తిస్తాం.',
  '4.6) దండ అయస్కాంతం N ధ్రువాన్ని దిక్సూచి N చివర దగ్గరకు తెస్తే సూది దూరంగా తిరుగుతుంది (వికర్షణ); S ధ్రువం తెస్తే సూది N చివర దగ్గరకు వస్తుంది (ఆకర్షణ).']),
 (132, 'కృత్యం 4.7 – పట్టిక 4.2', [
  'చెక్క, అట్ట, ప్లాస్టిక్, గాజు – ఏది మధ్యలో పెట్టినా సూది విచలనంలో గణనీయమైన మార్పు లేదు. ముగింపు: అయస్కాంత ప్రభావం అనయస్కాంత పదార్థాల గుండా పనిచేస్తుంది.']),
 (134, 'అయస్కాంతాలతో సరదా', [
  'అయస్కాంతాన్ని ట్రే కింద కదిలిస్తే ఉక్కు బంతులు చిక్కుదారి (maze) నుండి బయటికి వస్తాయి; గ్లాసు బయట నుండి అయస్కాంతంతో నీటిలోని క్లిప్‌ను వేళ్ళు తడవకుండా పైకి తీయవచ్చు (అయస్కాంత ప్రభావం గాజు, నీరు గుండా పనిచేస్తుంది).']),
 (136, 'అయస్కాంత కార్లు', [
  'సజాతి ధ్రువాలు ఎదురెదురుగా ఉంటే రెండు కార్లు ఒకదానికొకటి దూరంగా పరిగెడతాయి (వికర్షణ); విజాతి ధ్రువాలు ఎదురుగా ఉంటే దగ్గరకు వేగంగా వస్తాయి.']),
 (140, 'మన అభ్యసనాన్ని మెరుగుపరచుకుందాం – ప్ర.1–4', [
  '1) (i) ఆకర్షిస్తాయి; వికర్షిస్తాయి (ii) అయస్కాంత పదార్థాలు (iii) ఉత్తర–దక్షిణ (iv) రెండు.',
  '2) (i) F (ii) T (iii) F – చివర్లలో (ధ్రువాల వద్ద) ఎక్కువ (iv) T.',
  '3) N–N → వికర్షణ; S–N → ఆకర్షణ; S–S (లేదా N–N) → వికర్షణ.',
  '4) (i) A – 10, B – 2, C – 10. ధ్రువాల (చివర్ల) వద్ద ఎక్కువ పిన్నులు, మధ్యలో చాలా తక్కువ.']),
 (142, 'ప్ర.5–11', [
  '5) ఒక కడ్డీ చివరను మిగిలిన రెండింటి రెండు చివర్ల దగ్గరకు తెచ్చి చూడాలి. ఏ రెండు కడ్డీల మధ్య వికర్షణ కనిపిస్తుందో అవి అయస్కాంతాలు. ఏ కడ్డీతోనూ వికర్షణ చూపనిది ఇనుప ముక్క (దాని రెండు చివర్లూ ఆకర్షితమవుతాయి).',
  '6) గుర్తులున్న అయస్కాంతం N ధ్రువాన్ని గుర్తులు లేని అయస్కాంతం ఒక చివర దగ్గరకు తేవాలి. వికర్షిస్తే ఆ చివర N; ఆకర్షిస్తే ఆ చివర S (వికర్షణతో నిర్ధారించాలి).',
  '7) దారంతో మధ్యలో కట్టి స్వేచ్ఛగా వేలాడదీయాలి. అది ఆగినప్పుడు ఉత్తరం వైపు చూపే చివర ఉత్తర ధ్రువం (సూర్యుడు ఉదయించే వైపు తూర్పు అనుకొని ఉత్తరం కనుక్కోవచ్చు). దిక్సూచి దగ్గరకు తెచ్చి కూడా చూడవచ్చు – దిక్సూచి N ను వికర్షించే చివర N.',
  '8) దిక్సూచి ఉత్తర ధ్రువం భౌగోళిక ఉత్తరం వైపు చూపుతుంది. విజాతి ధ్రువాలు ఆకర్షిస్తాయి కాబట్టి భూమి అయస్కాంత దక్షిణ ధ్రువం భౌగోళిక ఉత్తరం దగ్గర, అయస్కాంత ఉత్తర ధ్రువం భౌగోళిక దక్షిణం దగ్గర ఉండాలి.',
  '9) స్క్రూడ్రైవర్ మొనను అయస్కాంతంతో ఒకే దిశలో పదే పదే రుద్ది అయస్కాంతంగా మార్చాలి (లేదా మొనకు చిన్న అయస్కాంతం అతికించాలి) – ఉక్కు స్క్రూలు దానికి అతుక్కుంటాయి.',
  '10) X, Y ల ఎదురెదురు ముఖాల్లో సజాతి ధ్రువాలు ఉన్నాయి – వికర్షణ వల్ల X కిందికి రాదు, తేలుతూ ఉంటుంది. X ను తీసి తిరగేసి (పైముఖం కిందికి) మళ్ళీ పెడితే విజాతి ధ్రువాలు ఎదురై X, Y కి అతుక్కుంటుంది.',
  '11) 5 = N కాబట్టి అదే అయస్కాంతం మరో చివర 6 = S. 5 కి అతుక్కున్న 4 = S (విజాతి ఆకర్షణ), కాబట్టి 3 = N. 3 కి అతుక్కున్న 2 = S, కాబట్టి 1 = N. → 1 – N, 2 – S, 3 – N, 4 – S, 6 – S.']),
 (144, 'మరింత నేర్చుకుందాం', [
  'వేర్వేరు అయస్కాంతాలు వేర్వేరు సంఖ్యలో పిన్నులు ఎత్తుతాయి – వాటి బలం (పరిమాణం, పదార్థం, ఆకారం) వేరు కాబట్టి.',
  'వేర్వేరు ఆకారాలు అవసరానికి తగ్గట్టు: U-అయస్కాంతం రెండు ధ్రువాలూ దగ్గరగా – బలంగా పట్టుకుంటుంది; వలయ అయస్కాంతాలు స్పీకర్లలో; డిస్క్ – ఫ్రిజ్ స్టిక్కర్లు. వైద్యంలో: MRI స్కానింగ్‌లో శక్తివంతమైన అయస్కాంతాలు వాడతారు.']),
]
